import { existsSync } from "node:fs";
import { join } from "node:path";
export const CANONICAL_PROJECT_ROOT = "bot";
export function resolveProjectRoot(rootDir) {
    if (existsSync(join(rootDir, "bot"))) {
        return "bot";
    }
    if (existsSync(join(rootDir, "agent"))) {
        return "agent";
    }
    return CANONICAL_PROJECT_ROOT;
}
export function projectPath(projectRoot, relativePath) {
    return `${projectRoot}/${relativePath}`;
}
export function remapCanonicalProjectPath(path, projectRoot) {
    if (projectRoot === CANONICAL_PROJECT_ROOT || !path.startsWith("bot/")) {
        return path;
    }
    return `agent/${path.slice("bot/".length)}`;
}
export function remapCanonicalProjectContents(contents, projectRoot) {
    return projectRoot === CANONICAL_PROJECT_ROOT ? contents : contents.replaceAll("bot/", "agent/");
}
